<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Blends & Recipes — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Curated essential oil combinations and safe-use notes. Mixes that may support uplift, calm, and focus." />
  <style>
    :root{--bg:#fcfff7;--ink:#1e1e1e;--muted:#666;--accent:#2c7a7b}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;background:var(--bg);color:var(--ink);-webkit-font-smoothing:antialiased}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 22px;background-image:url('assets/img/pattern.svg');background-position:top right}
    header .nav a{margin-left:12px;color:var(--muted);text-decoration:none}
    main{max-width:1000px;margin:24px auto;padding:0 18px}
    .hero{padding:18px;border-radius:12px;background:linear-gradient(180deg,rgba(44,122,123,0.06),transparent);margin-bottom:18px}
    h1{margin:0 0 8px}
    .muted{color:var(--muted)}

    .blends-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px}
    .blend{background:#fff;padding:14px;border-radius:12px;border:1px solid rgba(0,0,0,0.04)}
    .blend h3{margin:0 0 6px}
    .pill{display:inline-block;padding:6px 8px;background:rgba(44,122,123,0.08);color:var(--accent);border-radius:999px;font-weight:700;font-size:12px}

    .reveal{opacity:0;transform:translateY(12px);transition:opacity 520ms ease,transform 520ms ease}
    .reveal.visible{opacity:1;transform:none}
    @media(prefers-reduced-motion:reduce){.reveal{transition:none}}

    .blend pre{background:#f8f8f8;padding:8px;border-radius:8px;white-space:pre-wrap;font-family:monospace;font-size:13px}

    .planner-mini{margin-top:18px;padding:12px;background:linear-gradient(180deg,#fff,rgba(44,122,123,0.02));border-radius:12px}
    label{display:block;font-weight:700;margin-top:10px}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(0,0,0,0.06)}
    .controls{display:flex;gap:8px;margin-top:10px}
    button{background:var(--accent);color:white;border:0;padding:8px 10px;border-radius:8px;font-weight:700}
    .secondary{background:white;color:var(--accent);border:1px solid rgba(0,0,0,0.06)}

    footer{padding:18px;color:var(--muted);text-align:center;margin-top:18px}
  </style>
</head>
<body>
  <header>
    <div>
      <strong>{{BUSINESS_NAME}}</strong>
      <div class="muted">Thoughtful blends, lightly instructed</div>
    </div>
    <nav class="nav" aria-label="Main navigation">
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Blends</a>
      <a href="shop.html">Boutique</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <section class="hero reveal">
      <h1>Core blends</h1>
      <p class="muted">Short recipes meant for diffusers, personal inhalers, or careful topical with dilution. Each recipe includes quick safety notes.</p>
    </section>

    <section class="blends-grid">
      <article class="blend reveal">
        <div class="pill">Calm</div>
        <h3>Evening hush</h3>
        <pre>Top notes: Bergamot 2 drops\nHeart: Lavender 3 drops\nBase: Vetiver 1 drop\nDilution: 1–2% for topical; diffuse briefly. Patch test advised.</pre>
      </article>

      <article class="blend reveal">
        <div class="pill">Focus</div>
        <h3>Clearline</h3>
        <pre>Top: Sweet Orange 2 drops\nHeart: Rosemary 1 drop\nAccord: Cedarwood 1 drop\nUse in personal inhaler or a short diffuser session.</pre>
      </article>

      <article class="blend reveal">
        <div class="pill">Lift</div>
        <h3>Bright Harbor</h3>
        <pre>Top: Grapefruit 2 drops\nHeart: Lavender 1 drop\nHint: Petitgrain 1 drop\nGreat as a quick, daytime diffuser blend.</pre>
      </article>

      <article class="blend reveal">
        <div class="pill">Soften</div>
        <h3>Quiet Anchor</h3>
        <pre>Top: Mandarin 2 drops\nHeart: Geranium 1 drop\nBase: Sandalwood 1 drop\nKeep low concentration; monitor for skin sensitivity.</pre>
      </article>
    </section>

    <section class="planner-mini reveal" aria-labelledby="mini-planner">
      <h2 id="mini-planner">Mini Session Planner</h2>
      <p class="muted">Choose an intention and get a short recipe and practice note you can copy.</p>
      <label for="miniInt">Intention</label>
      <select id="miniInt">
        <option value="calm">Calm</option>
        <option value="focus">Focus</option>
        <option value="lift">Lift</option>
      </select>
      <div class="controls">
        <button id="miniBuild">Create</button>
        <button id="miniCopy" class="secondary">Copy</button>
      </div>
      <textarea id="miniOut" style="width:100%;margin-top:8px;height:90px;font-family:monospace" readonly></textarea>
    </section>

    <section class="reveal" style="margin-top:18px">
      <h3>Notes</h3>
      <p class="muted">If you are pregnant, nursing, have severe allergies, or keep pets, please review blend contents and discuss adaptations before use. This information is educational, not medical advice.</p>
    </section>

    <section class="reveal" style="margin-top:18px;display:flex;gap:12px;align-items:center;justify-content:space-between">
      <div class="muted">Want curated bottles? Visit the Boutique for ready-to-use options.</div>
      <a href="shop.html" class="pill" style="text-decoration:none">Browse bottles</a>
    </section>
  </main>

  <footer>
    <div>Questions? Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call {{PHONE}}</div>
  </footer>

  <script>
    // reveal
    (function(){
      var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      if(reduced){document.querySelectorAll('.reveal').forEach(function(e){e.classList.add('visible')});return}
      var obs = new IntersectionObserver(function(entries){entries.forEach(function(en){if(en.isIntersecting){en.target.classList.add('visible');obs.unobserve(en.target)}});},{threshold:0.12});
      document.querySelectorAll('.reveal').forEach(function(el){obs.observe(el)});
    })();

    // Mini planner
    (function(){
      var build = document.getElementById('miniBuild');
      var out = document.getElementById('miniOut');
      var copy = document.getElementById('miniCopy');
      function make(int){
        var s = [];
        s.push('Intention: '+int);
        if(int==='calm'){
          s.push('Recipe: Lavender 3, Bergamot 2, Vetiver 1');
          s.push('Use: Diffuse before rest; dilute for skin.');
        } else if(int==='focus'){
          s.push('Recipe: Sweet Orange 2, Rosemary 1, Cedarwood 1');
          s.push('Use: Personal inhaler or 10-min diffuser bursts.');
        } else {
          s.push('Recipe: Grapefruit 2, Lavender 1, Petitgrain 1');
          s.push('Use: Short daytime boosts; avoid late evening if sensitive.');
        }
        s.push('Safety: Patch test for topical; consider pet-safe ventilation.');
        return s.join('\n');
      }
      build.addEventListener('click',function(){out.value=make(document.getElementById('miniInt').value)});
      copy.addEventListener('click',function(){if(!out.value) return; navigator.clipboard.writeText(out.value).then(function(){copy.textContent='Copied'; setTimeout(function(){copy.textContent='Copy'},1000)})});
    })();
  </script>
</body>
</html>"} 
