<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Boutique — {{BUSINESS_NAME}}</title>
  <meta name="description" content="A small collection of blends and ritual kits. Products include safety guidance and suggested dilution." />
  <style>
    :root{--bg:#fffdf8;--ink:#151515;--muted:#666;--accent:#a55a39}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;background:var(--bg);color:var(--ink)}
    header{display:flex;justify-content:space-between;align-items:center;padding:16px 20px;background-image:url('assets/img/pattern.svg')}
    header nav a{margin-left:12px;color:var(--muted);text-decoration:none}
    main{max-width:1100px;margin:20px auto;padding:0 18px}
    .hero{padding:16px;border-radius:10px;background:linear-gradient(180deg,rgba(165,90,57,0.04),transparent)}
    .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px;margin-top:14px}
    .card{background:#fff;padding:14px;border-radius:12px;border:1px solid rgba(0,0,0,0.04)}
    .card h3{margin:0 0 8px}
    .price{font-weight:800;margin-top:6px}
    .small{font-size:13px;color:var(--muted)}

    .reveal{opacity:0;transform:translateY(12px);transition:opacity 520ms ease,transform 520ms ease}
    .reveal.visible{opacity:1;transform:none}
    @media(prefers-reduced-motion:reduce){.reveal{transition:none}}

    .planner-inline{margin-top:18px;padding:12px;border-radius:12px;background:linear-gradient(180deg,#fff,rgba(165,90,57,0.02))}
    label{display:block;margin-top:10px;font-weight:700}
    select,input{width:100%;padding:8px;border-radius:8px;border:1px solid rgba(0,0,0,0.06)}
    button{background:var(--accent);color:#fff;border:0;padding:8px 10px;border-radius:8px;font-weight:700}
    .outline{background:#fff;border:1px solid rgba(0,0,0,0.06);color:var(--accent)}

    footer{padding:20px;text-align:center;color:var(--muted)}
  </style>
</head>
<body>
  <header>
    <div>
      <strong>{{BUSINESS_NAME}}</strong>
      <div class="small">A small shop of simple rituals</div>
    </div>
    <nav aria-label="Shop navigation">
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Blends</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="hero reveal">
      <h1>Boutique</h1>
      <p class="small">Selected, small-batch blends, personal inhalers, and starter ritual kits. Each item includes guidance on dilution and safe use.</p>
    </section>

    <section class="grid" aria-label="Products">
      <article class="card reveal">
        <h3>Inhaler — Calm</h3>
        <div class="small">Portable inhaler with a subtle lavender-led accord. 1 per pack.</div>
