  <script>
    // reveal
    (function(){
      var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      if(reduced){document.querySelectorAll('.reveal').forEach(function(e){e.classList.add('visible')});return}
      var obs = new IntersectionObserver(function(entries){entries.forEach(function(en){if(en.isIntersecting){en.target.classList.add('visible');obs.unobserve(en.target)}});},{threshold:0.12});
      document.querySelectorAll('.reveal').forEach(function(el){obs.observe(el)});
    })();

    // Planner + product collect
    (function(){
      var items = [];
      var planItems = document.getElementById('planItems');
      function refresh(){
        planItems.value = items.length ? items.map(function(i,idx){return (idx+1)+'. '+i}).join('\n') : '';
      }
      document.querySelectorAll('.buy').forEach(function(btn){
        btn.addEventListener('click',function(){
          var sku = btn.getAttribute('data-sku');
          var titleMap = { 'inhaler-calm':'Inhaler — Calm', 'blend-focus':'Diffuser Blend — Focus', 'kit-starter':'Starter Ritual Kit', 'roll-lift':'Roll-on — Lift' };
          items.push(titleMap[sku]||sku);
          refresh();
          btn.textContent='Added';
          setTimeout(function(){btn.textContent='Add to Plan'},900);
        });
      });

      document.getElementById('copyPlan').addEventListener('click',function(){
        var goal = document.getElementById('planGoal').value;
        var text = 'Shopping & session plan\nIntention: '+goal+'\n\nItems:\n'+(planItems.value||'(none)')+'\n\nBooking: '+ '{{PRIMARY_CTA_URL}}';
        navigator.clipboard.writeText(text).then(function(){document.getElementById('copyPlan').textContent='Copied';setTimeout(function(){document.getElementById('copyPlan').textContent='Copy plan'},900)});
      });

      document.getElementById('clearPlan').addEventListener('click',function(){items=[];refresh()});

      // details buttons simply show a quick alert for now
      document.querySelectorAll('.view').forEach(function(b){b.addEventListener('click',function(){var sku=b.getAttribute('data-sku');alert('Details for '+sku+'\nSafety: dilute for skin; keep away from pets; patch test before use.');})});
    })();
  </script>
